#!<path> bash
# Merge every data/*.csv into snapshot/all.csv, header once, rows sorted.
set -euo pipefail

mkdir -p snapshot
{
    echo "region,day,orders"
    tail -q -n +2 data/*.csv | sort
} > snapshot/all.csv
#!<path> bash
# Rebuild the nightly snapshot and commit it to main when it changed.
set...
